	public Promotion removeFromChannels( UUID parentId, Channel removeFrom ) {
	    LOGGER.info("handling RemoveChannelsFromPromotionEvent " );
	
	    Promotion parentEntity = repository.findById(parentId).get();
	    Channel child = registry.project( Channel.class, removeFrom.getChannelId());
	    
	    parentEntity.getChannels().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

